[Form]
public class GUPAddPriceAttributeGroup extends FormRun
{
    private GUPPricingRule currentRule;
    private GUPPricingAttributeGroup currentAttributeGroup;
    private GUPPricingAttributeSourceLevel sourceLevel;
    private Query inventTablePreviewQuery;
    private Query custTablePreviewQuery;
    private Query productVariantPreviewQuery;
    private boolean addProductvariants = false;

}

/// <summary>
/// Form initialization method.
/// </summary>
public void init()
{
    xArgs args = this.args();

    // get pricing rule object and set query link.
    GUPPricingRule rule = args.record();

    if (args.parmEnumType() == enumNum(GUPPricingAttributeSourceLevel))
    {
        this.sourceLevel = args.parmEnum();
    }

    super();

    GUPPricingAttributeGroup attributeGroup;
    if (!rule.RecId)
    {
        throw error("@GlobalUnifiedPricing:GUPPricingRule_InsertFirst");
    }
    else if (rule.PriceAttributeGroup)
    {
        select firstonly attributeGroup where attributeGroup.RecId == rule.PriceAttributeGroup;
    }

    this.currentRule = rule;
    this.addProductvariants = (rule.ExclusionType == GUPPricingRuleExclusionType::ProductVariant);
    this.currentAttributeGroup = attributeGroup;

    currentRule.selectForUpdate(true);

    this.initFormControls();
    this.initFormPricingObjectPreviewQuery();
    this.selectPricingAttributeGroup();
    this.toggleInventTableProductVariantPreviewVisibility();
}

private void initFormControls()
{
    PriceAttributeGroup_SourceLevel.text(enum2Str(this.sourceLevel));

    if (currentAttributeGroup.RecId)
    {
        switch (element.sourceLevel)
        {
            case GUPPricingAttributeSourceLevel::Header:
                CustTablePreview.enabled(true);
                CustTablePreview.visible(true);
                break;
            case GUPPricingAttributeSourceLevel::Line:
                InventTablePreview.enabled(true);
                InventTablePreview.visible(true);
                break;
        }
    }
}

private void initFormPricingObjectPreviewQuery()
{
    Query inventTableQuery, custTableQuery, productVariantQuery;

    custTableQuery = new Query();
    custTableQuery.addDataSource(tableNum(CustTable))
        .addRange(fieldNum(CustTable, RecId))
        .value(int2Str(-1));

    inventTableQuery = new Query();
    inventTableQuery.addDataSource(tableNum(InventTable))
        .addRange(fieldNum(InventTable, RecId))
        .value(int2Str(-1));

    productVariantQuery = new Query();
    productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
        .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
        .value(int2Str(-1));

    element.inventTablePreviewQuery = inventTableQuery;
    element.custTablePreviewQuery = custTableQuery;
    element.productVariantPreviewQuery = productVariantQuery;
}

private void selectPricingAttributeGroup(GUPPricingAttributeGroup _attributeGroup = currentAttributeGroup)
{
    this.currentAttributeGroup = _attributeGroup;
    if (currentRule.PriceAttributeGroup != _attributeGroup.RecId && _attributeGroup.RecId)
    {
        ttsbegin;
        currentRule.clearRuleConditions();
        currentRule.initPricingRule(_attributeGroup);
        ttscommit;
    }

    this.displayPricingAttributeGroupDetail();
    GUPPricingRuleCondition_ds.executeQuery();

    switch (element.sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            if (_attributeGroup)
            {
                CustTablePreview.enabled(true);
                CustTablePreview.visible(true);
                element.custTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(element.currentRule).build();
                CustTable_ds.executeQuery();
            }
            else
            {
                CustTablePreview.enabled(false);
                CustTablePreview.visible(false);
            }
            break;
        case GUPPricingAttributeSourceLevel::Line:
            if (_attributeGroup)
            {
                if (!addProductvariants)
                {
                    inventTablePreview.enabled(true);
                    inventTablePreview.visible(true);
                    element.inventTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(element.currentRule)
                        .build();
                    InventTable_ds.executeQuery();
                }
                else
                {
                    ProductVariantPreview.enabled(true);
                    ProductVariantPreview.visible(true);
                    element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(element.currentRule)
                        .addProductVariants()
                        .build();
                    EcoResDistinctProductVariant_ds.executeQuery();
                }
            }
            else
            {
                inventTablePreview.enabled(false);
                inventTablePreview.visible(false);
                ProductVariantPreview.enabled(false);
                ProductVariantPreview.visible(false);
            }
            break;
    }
}

private void displayPricingAttributeGroupDetail()
{
    PriceAttributeGroup_Name.text(currentAttributeGroup.Name);
    PriceAttributeGroup_Description.text(currentAttributeGroup.Description);
}

private void togglePricingRuleIncludeExcludeButtonVisibility(boolean _showExclude)
{
    switch (element.sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            ExcludeCustAcc.visible(_showExclude);
            IncludeCustAcc.visible(!_showExclude);
            break;
        case GUPPricingAttributeSourceLevel::Line:
            ExcludeItemId.visible(_showExclude);
            IncludeItemId.visible(!_showExclude);
            ExcludeProductVariant.visible(_showExclude);
            IncludeProductVariant.visible(!_showExclude);
            break;
    }
}

private void toggleInventTableProductVariantPreviewVisibility(boolean _addProductVariants = addProductvariants)
{
    element.addProductvariants = _addProductVariants;
    if (element.sourceLevel == GUPPricingAttributeSourceLevel::Line
        && element.currentAttributeGroup
        && element.currentAttributeGroup.matchSource(GUPPricingAttributeSource::Product))
    {
        InventTablePreview.enabled(!_addProductVariants);
        InventTablePreview.visible(!_addProductVariants);
        ProductVariantPreview.enabled(_addProductVariants);
        ProductVariantPreview.visible(_addProductVariants);

        if (_addProductVariants)
        {
            Query inventTableQuery = new Query();
            inventTableQuery.addDataSource(tableNum(InventTable))
                .addRange(fieldNum(InventTable, RecId))
                .value(int2Str(-1));

            element.inventTablePreviewQuery = inventTableQuery;
            element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(element.currentRule)
                    .addProductVariants()
                    .build();
            EcoResDistinctProductVariant_ds.executeQuery();
            ProductVariantPreview.fastTabExpanded(FastTabExpanded::Yes);
        }
        else
        {
            Query productVariantQuery = new Query();
            productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
                .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
                .value(int2Str(-1));

            element.productVariantPreviewQuery = productVariantQuery;
            element.inventTablePreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(element.currentRule)
                    .build();
            InventTable_ds.executeQuery();
        }
    }
}

internal Common masterRecord()
{
    return element.currentRule;
}

public boolean closed()
{
    boolean ret;

    ret = super();

    element.args().caller();

    if (formHasMethod(element.args().caller(), identifierStr(refreshFormDatasource)))
    {
        element.args().caller().refreshFormDatasource(element.sourceLevel);
    }

    return ret;
}

private void clearRuleExclusions(GUPPricingRuleExclusionType _exclusionType)
{
    ttsbegin;

    currentRule.ExclusionType = _exclusionType;
    currentRule.clearRuleExclusions();
    currentRule.update();

    ttscommit;
}

public int active()
{
    int ret;

    ret = super();
    this.queryBuildDataSource()
        .addDynalink(fieldNum(GUPPricingRule, RecId), element.currentRule, fieldNum(GUPPricingRule, RecId));

    return ret;
}

public display Name displayPricingAttributeName(GUPPricingRuleCondition _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleCondition _ruleCondition, Name _name)
{
    if (_set)
    {
        if (strCmp(strLRTrim( _ruleCondition.priceAttributeLink().AttributeName), GUPPricingAttributeAllowedValueLookup::NEED_HIERARCHICAL_ATTRIBUTE_NAME) == 0
            && Checkbox_AppendValueOnLookup.checked()
            && strLen(_ruleCondition.ConditionValue) > 0)
        {
            boolean categoryAlreadyAdded = false;
            ListEnumerator existingCategoriesListEnumerator = strSplit(_ruleCondition.ConditionValue, ",").getEnumerator();
            while (existingCategoriesListEnumerator.moveNext())
            {
                if (existingCategoriesListEnumerator.current() == _name)
                {
                    categoryAlreadyAdded = true;
                    break;
                }
            }
            if (!categoryAlreadyAdded)
            {
                _ruleCondition.ConditionValue +=  "," + _name;
            }
        }
        else
        {
            _ruleCondition.ConditionValue = _name;
        }

        element.clearRuleExclusions(currentRule.ExclusionType);
        element.togglePricingRuleIncludeExcludeButtonVisibility(true);
    }
    return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(_ruleCondition.priceAttributeLink().AttributeName, _ruleCondition.ConditionValue);
}

public void executeQuery()
{
    Query query = new Query();
    query.addDataSource(tableNum(GUPPricingRuleCondition))
        .addDynalink(fieldNum(GUPPricingRuleCondition, RuleId), element.currentRule, fieldNum(GUPPricingRule, RecId));
    this.query(query);

    super();
}

public void executeQuery()
{
    Query query = new Query();
    query.addDataSource(tableNum(GUPPricingAttributeGroup))
        .addDynalink(fieldNum(GUPPricingAttributeGroup, RecId), element.currentAttributeGroup, fieldNum(GUPPricingAttributeGroup, RecId));
    this.query(query);

    super();
}

public void executeQuery()
{
    this.query(element.custTablePreviewQuery);
    super();
}

public display str displayCustTableExclusion(CustTable _custTable)
{
    GUPPricingRuleExclusion excluded;
    select firstonly RecId from excluded where excluded.Exclusion == _custTable.AccountNum && excluded.RuleId == currentRule.RecId;

    if (excluded.RecId)
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Exclude";
    }
    else
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Include";
    }
}

public void markChanged()
{
    super();

    MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();
    CustTable custTableExclusion;
    selectionHelper.parmDatasource(CustTable_ds);
    custTableExclusion = selectionHelper.getFirst();

    while (custTableExclusion)
    {
        if (currentRule.isExcluded(custTableExclusion.AccountNum))
        {
            element.togglePricingRuleIncludeExcludeButtonVisibility(false);
            return;
        }
        custTableExclusion = selectionHelper.getNext();
    }

    element.togglePricingRuleIncludeExcludeButtonVisibility(true);
}

public void executeQuery()
{
    this.query(element.inventTablePreviewQuery);
    super();
}

