public void clicked()
{            
    GUPPricingRule rule = element.args().record();
    if (!PriceAttributeGroup_Name.valueStr() && rule.PriceAttributeGroup == 0 && element.args().caller() is GUPIEnableDisableForm)
    {
        GUPIEnableDisableForm callerForm = element.args().caller() as GUPIEnableDisableForm;

        ttsbegin;

        callerForm.postDeleteEmptyPricingRule();
        delete_from GUPPricingRule where GUPPricingRule.RecId == rule.RecId;

        ttscommit;
    }
    super();
}
